{
  "name": "opencode-groq-dictate",
  "version": "1.1.14",
  "description": "Groq dictation in the OpenCode v2 TUI: alt+v records, transcribes with whisper-large-v3-turbo, and pastes the text into the prompt.",
  "private": false,
  "type": "module",
  "exports": {
    "./tui": "./tui.tsx"
  },
  "scripts": {
    "test": "bun test"
