  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "dictation",
    "groq",
    "whisper"
  ],
  "license": "MIT",
  "author": "Leonardo Cosmai",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/LeonVeganMan/opencode-groq-dictate.git"
  },
  "homepage": "https://github.com/LeonVeganMan/opencode-groq-dictate#readme",
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "latest"
  }
}
